def nys_cv(a=1.0,b=0.0,nanch=1000,lam=0.005,c0=0.5,seeds=(0,1,2),k=10,Z=Z9,C=C0,yv=y,jit=1e-6):
    accs=[]; n=len(yv); Yv=np.eye(8)[yv]
    for s in seeds:
        f=folds(yv,k,s); S=np.zeros((n,8)); rng=np.random.RandomState(100+s)
        for i in range(k):
            tr=np.where(f!=i)[0]; te=np.where(f==i)[0]
            anc=rng.choice(tr, min(nanch,len(tr)), replace=False)
            Phi=gelu(a*(Z@Z[anc].T)+b); Kaa=gelu(a*(Z[anc]@Z[anc].T)+b)
            na=len(anc)
            if c0>0:
                F=np.hstack([Phi, C]); Pen=np.zeros((na+C.shape[1],)*2); Pen[:na,:na]=Kaa+jit*np.eye(na); Pen[na:,na:]=np.eye(C.shape[1])/c0
            else:
                F=Phi; Pen=Kaa+jit*np.eye(na)
            mu=F[tr].mean(0); Fc=F-mu
            Wt=np.linalg.solve(Fc[tr].T@Fc[tr]+lam*Pen, Fc[tr].T@(Yv[tr]-Yv[tr].mean(0)))
            S[te]=Fc[te]@Wt
        accs.append((S.argmax(1)==yv).mean())
    return round(float(np.mean(accs)),4)
